import numpy as np
from scipy.optimize import curve_fit

x=[];y=[]
for line in open('/app/graphene.dat'):
    a,b=line.split();x.append(float(a.replace(',','.')));y.append(float(b.replace(',','.')))
x=np.array(x);y=np.array(y)
idx=np.argsort(x);x=x[idx];y=y[idx]
nu=1e7/x
idx=np.argsort(nu);nu=nu[idx];yy=y[idx]

def lor_const(t,x0,g,A,off):
    return off + A*g*g/((t-x0)**2+g*g)

def lor_lin(t,x0,g,A,off,sl):
    return off + sl*(t-x0) + A*g*g/((t-x0)**2+g*g)

def fit(t,yy,window,model,p0):
    m=(t>=window[0])&(t<=window[1])
    tt=t[m]; Y=yy[m]
    popt,pcov=curve_fit(model,tt,Y,p0=p0,maxfev=200000)
    resid=Y-model(tt,*popt)
    return popt, np.sqrt(np.mean(resid**2)), m.sum()

for name,window,p0 in [('G',(1450,1720),[1580,15,4000,5000]),
                       ('2D',(2500,2900),[2680,30,6000,5000])]:
    for mod,lab in [(lor_const,'const'),(lor_lin,'linear')]:
        p0x=p0 if lab=='const' else p0+[0]
        popt,rms,n=fit(nu,yy,window,mod,p0x)
        print(name,lab,'x0,g,A,off'+',slope'*('lin' in lab),popt,'rms',rms,'n',n)
print('--- raw x domain ---')
for name,window,p0 in [('G',(6100,6600),[6329,40,4000,5000]),
                       ('2D',(3500,4000),[3731,50,6000,5000])]:
